/*
  BathroomMusic Controller - ESP32
  Hardware:
    LDR module S  -> GPIO34
    LDR +         -> 3V3
    LDR -         -> GND

    DFPlayer TX   -> ESP32 GPIO16 (RX2)
    DFPlayer RX   -> ESP32 GPIO17 (TX2) through 1k resistor
    DFPlayer VCC  -> ESP32 5V/VIN (board powered by USB)
    DFPlayer GND  -> ESP32 GND
    DFPlayer DAC_R -> audio breakout RING1
    DFPlayer DAC_L -> audio breakout TIP
    DFPlayer GND   -> audio breakout SLEEVE

  Wi-Fi AP: BathroomMusic
  Password: Music1234
  Web page: http://192.168.4.1

  For first test, the firmware plays the first track found on the SD card.
  If the file does not play, rename it to /mp3/0001.mp3 on the card.
*/

#include <WiFi.h>
#include <WebServer.h>
#include <DFRobotDFPlayerMini.h>

const char* AP_SSID = "BathroomMusic";
const char* AP_PASSWORD = "Music1234";

constexpr int LDR_PIN = 34;
constexpr int DFPLAYER_RX_PIN = 16;  // ESP32 receives from DFPlayer TX
constexpr int DFPLAYER_TX_PIN = 17;  // ESP32 sends to DFPlayer RX

constexpr int LIGHT_ON_THRESHOLD = 3000;
constexpr int LIGHT_HYSTERESIS = 180;

WebServer server(80);
HardwareSerial dfSerial(2);
DFRobotDFPlayerMini player;

bool playerDetected = false;
bool automaticMode = true;
bool lightIsOn = false;
bool isPlaying = false;
bool hasStartedForCurrentLight = false;
int volumeLevel = 10;  // DFPlayer range 0-30
int lastLdrValue = 0;
String statusMessage = "Starting up";

String htmlEscape(const String& s) {
  String out = s;
  out.replace("&", "&amp;");
  out.replace("<", "&lt;");
  out.replace(">", "&gt;");
  out.replace("\"", "&quot;");
  return out;
}

String pageHtml() {
  String playerState = !playerDetected ? "Not detected" : (isPlaying ? "Playing" : "Stopped / paused");
  String lightState = lightIsOn ? "Light detected as ON" : "Light detected as OFF";
  String autoState = automaticMode ? "Automatic" : "Manual";
  String detectedState = playerDetected ? "Connected" : "Not detected";
  String disabled = playerDetected ? "" : "disabled";

  String html = R"HTML(
<!doctype html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Bathroom Music</title>
<style>
:root{color-scheme:light;--bg:#f3f5f8;--card:#fff;--ink:#172033;--muted:#647087;--accent:#2457d6;--border:#dfe5ef;--good:#16794b;--bad:#a33a35}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.5 system-ui,-apple-system,Segoe UI,Roboto,sans-serif}
main{max-width:760px;margin:0 auto;padding:22px 16px 36px}
header{margin-bottom:18px}
h1{font-size:clamp(1.7rem,5vw,2.2rem);margin:0 0 4px}
.subtitle{color:var(--muted);margin:0}
.card{background:var(--card);border:1px solid var(--border);border-radius:16px;padding:18px;margin:14px 0;box-shadow:0 3px 12px #18294a08}
h2{font-size:1.08rem;margin:0 0 12px}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:10px}
.stat{background:#f7f9fc;border-radius:12px;padding:12px}
.label{color:var(--muted);font-size:.84rem}
.value{font-size:1.05rem;font-weight:700;margin-top:3px;overflow-wrap:anywhere}
button,a.button{font:inherit;font-weight:650;display:inline-flex;justify-content:center;align-items:center;min-height:44px;padding:10px 14px;border:0;border-radius:10px;background:var(--accent);color:#fff;text-decoration:none;cursor:pointer}
button.secondary,a.secondary{background:#e9eef9;color:#20365f}
button.danger{background:#a33a35}
button:disabled{opacity:.4;cursor:not-allowed}
.actions{display:flex;flex-wrap:wrap;gap:9px}
.row{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}
input[type=range]{width:100%;accent-color:var(--accent)}
.small{font-size:.9rem;color:var(--muted)}
.pill{display:inline-block;border-radius:999px;padding:3px 9px;background:#e8edf6;font-size:.82rem;font-weight:700}
.pill.good{background:#dff5e8;color:var(--good)}
.pill.bad{background:#fde9e7;color:var(--bad)}
.notice{margin-top:10px;color:var(--muted);font-size:.9rem}
</style>
</head>
<body>
<main>
<header>
  <h1>🎵 Bathroom Music</h1>
  <p class="subtitle">Simple controls for your music player and light sensor.</p>
</header>
<section class="card">
  <h2>Current status</h2>
  <div class="grid">
    <div class="stat"><div class="label">DFPlayer</div><div class="value" id="player">)HTML" + htmlEscape(detectedState) + R"HTML(</div></div>
    <div class="stat"><div class="label">Playback</div><div class="value" id="playback">)HTML" + htmlEscape(playerState) + R"HTML(</div></div>
    <div class="stat"><div class="label">Control mode</div><div class="value" id="mode">)HTML" + htmlEscape(autoState) + R"HTML(</div></div>
    <div class="stat"><div class="label">Light sensor</div><div class="value" id="light">)HTML" + htmlEscape(lightState) + R"HTML(</div></div>
    <div class="stat"><div class="label">Sensor reading</div><div class="value" id="ldr">)HTML" + String(lastLdrValue) + R"HTML( / 4095</div></div>
    <div class="stat"><div class="label">Volume</div><div class="value" id="volumeText">)HTML" + String(volumeLevel) + R"HTML( / 30</div></div>
  </div>
  <p class="notice" id="message">)HTML" + htmlEscape(statusMessage) + R"HTML(</p>
</section>
<section class="card">
  <h2>Music controls</h2>
  <div class="actions">
    <button onclick="send('/play')" )HTML" + disabled + R"HTML(>▶ Play test track</button>
    <button class="secondary" onclick="send('/pause')" )HTML" + disabled + R"HTML(>⏸ Pause / resume</button>
    <button class="danger" onclick="send('/stop')" )HTML" + disabled + R"HTML(>■ Stop</button>
  </div>
  <p class="small">For this test, Play starts the first track the DFPlayer finds on the SD card.</p>
</section>
<section class="card">
  <div class="row"><h2>Automatic control</h2><span class="pill" id="modePill">)HTML" + htmlEscape(autoState) + R"HTML(</span></div>
  <p class="small">When Automatic is on, the sensor starts music when the light turns on and stops it when the light turns off.</p>
  <div class="actions"><button class="secondary" id="modeButton" onclick="send('/mode')">Switch to )HTML" + String(automaticMode ? "Manual" : "Automatic") + R"HTML( mode</button></div>
</section>
<section class="card">
  <h2>Volume</h2>
  <div class="row"><label for="vol">Volume</label><strong id="volLabel">)HTML" + String(volumeLevel) + R"HTML( / 30</strong></div>
  <input id="vol" type="range" min="0" max="30" value=")HTML" + String(volumeLevel) + R"HTML(" oninput="document.getElementById('volLabel').textContent=this.value+' / 30'" onchange="send('/volume?v='+this.value)">
  <p class="small">Start low and increase gradually.</p>
</section>
<section class="card">
  <h2>Light sensor</h2>
  <div class="actions"><button class="secondary" onclick="send('/lighttest')">Test sensor reading</button></div>
  <p class="small">The reading should change when the room light switches on and off. If it behaves backwards, we can adjust the sensor logic later.</p>
</section>
</main>
<script>
async function send(path){
  try{const r=await fetch(path,{cache:'no-store'});const t=await r.text();document.getElementById('message').textContent=t;await refresh();}
  catch(e){document.getElementById('message').textContent='Could not reach the ESP32. Check that you are connected to BathroomMusic.';}
}
async function refresh(){
  try{
    const r=await fetch('/status',{cache:'no-store'});const s=await r.json();
    document.getElementById('player').textContent=s.playerDetected?'Connected':'Not detected';
    document.getElementById('playback').textContent=s.playing?'Playing':(s.playerDetected?'Stopped / paused':'Not available');
    document.getElementById('mode').textContent=s.automatic?'Automatic':'Manual';
    document.getElementById('modePill').textContent=s.automatic?'Automatic':'Manual';
    document.getElementById('modeButton').textContent='Switch to '+(s.automatic?'Manual':'Automatic')+' mode';
    document.getElementById('light').textContent=s.lightOn?'Light detected as ON':'Light detected as OFF';
    document.getElementById('ldr').textContent=s.ldr+' / 4095';
    document.getElementById('volumeText').textContent=s.volume+' / 30';
    document.getElementById('vol').value=s.volume;
    document.getElementById('volLabel').textContent=s.volume+' / 30';
  }catch(e){}
}
setInterval(refresh,2000);refresh();
</script>
</body>
</html>
)HTML";
  return html;
}

void handleRoot() {
  server.send(200, "text/html; charset=utf-8", pageHtml());
}

void handleStatus() {
  String json = "{";
  json += "\"playerDetected\":" + String(playerDetected ? "true" : "false") + ",";
  json += "\"playing\":" + String(isPlaying ? "true" : "false") + ",";
  json += "\"automatic\":" + String(automaticMode ? "true" : "false") + ",";
  json += "\"lightOn\":" + String(lightIsOn ? "true" : "false") + ",";
  json += "\"ldr\":" + String(lastLdrValue) + ",";
  json += "\"volume\":" + String(volumeLevel);
  json += "}";
  server.send(200, "application/json", json);
}

void handlePlay() {
  if (!playerDetected) {
    server.send(503, "text/plain; charset=utf-8", "DFPlayer not detected. Check power, SD card, TX/RX and GND.");
    return;
  }
  player.play(1);
  isPlaying = true;
  statusMessage = "Play command sent to the first track on the SD card.";
  server.send(200, "text/plain; charset=utf-8", statusMessage);
}

void handlePause() {
  if (!playerDetected) {
    server.send(503, "text/plain; charset=utf-8", "DFPlayer is not detected yet.");
    return;
  }
  if (isPlaying) {
    player.pause();
    isPlaying = false;
    statusMessage = "Pause command sent.";
  } else {
    player.start();
    isPlaying = true;
    statusMessage = "Resume command sent.";
  }
  server.send(200, "text/plain; charset=utf-8", statusMessage);
}

void handleStop() {
  if (!playerDetected) {
    server.send(503, "text/plain; charset=utf-8", "DFPlayer is not detected yet.");
    return;
  }
  player.stop();
  isPlaying = false;
  hasStartedForCurrentLight = false;
  statusMessage = "Stop command sent.";
  server.send(200, "text/plain; charset=utf-8", statusMessage);
}

void handleMode() {
  automaticMode = !automaticMode;
  hasStartedForCurrentLight = false;
  statusMessage = automaticMode ? "Automatic mode enabled." : "Manual mode enabled.";
  server.send(200, "text/plain; charset=utf-8", statusMessage);
}

void handleVolume() {
  if (!server.hasArg("v")) {
    server.send(400, "text/plain; charset=utf-8", "Missing volume value.");
    return;
  }
  volumeLevel = constrain(server.arg("v").toInt(), 0, 30);
  if (playerDetected) player.volume(volumeLevel);
  statusMessage = "Volume set to " + String(volumeLevel) + " / 30.";
  server.send(200, "text/plain; charset=utf-8", statusMessage);
}

void handleLightTest() {
  lastLdrValue = analogRead(LDR_PIN);
  statusMessage = "Current sensor reading: " + String(lastLdrValue) + " / 4095.";
  server.send(200, "text/plain; charset=utf-8", statusMessage);
}

void setup() {
  Serial.begin(115200);
  delay(250);

  analogReadResolution(12);
  pinMode(LDR_PIN, INPUT);
  lastLdrValue = analogRead(LDR_PIN);
  lightIsOn = lastLdrValue < LIGHT_ON_THRESHOLD;

  WiFi.mode(WIFI_AP);
  WiFi.softAP(AP_SSID, AP_PASSWORD);

  Serial.println();
  Serial.println("BathroomMusic starting");
  Serial.print("Wi-Fi: "); Serial.println(AP_SSID);
  Serial.print("Web page: http://"); Serial.println(WiFi.softAPIP());

  dfSerial.begin(9600, SERIAL_8N1, DFPLAYER_RX_PIN, DFPLAYER_TX_PIN);
  delay(1200);

  // isACK=false avoids waiting for replies from some clone modules.
  playerDetected = player.begin(dfSerial, false, true);
  if (playerDetected) {
    player.setTimeOut(500);
    player.volume(volumeLevel);
    player.EQ(DFPLAYER_EQ_NORMAL);
    player.outputDevice(DFPLAYER_DEVICE_SD);
    statusMessage = "DFPlayer connected. Ready to test playback.";
    Serial.println("DFPlayer detected.");
  } else {
    statusMessage = "DFPlayer not detected. Web controls are available; check wiring and SD card.";
    Serial.println("DFPlayer not detected. Check wiring and SD card.");
  }

  server.on("/", HTTP_GET, handleRoot);
  server.on("/status", HTTP_GET, handleStatus);
  server.on("/play", HTTP_GET, handlePlay);
  server.on("/pause", HTTP_GET, handlePause);
  server.on("/stop", HTTP_GET, handleStop);
  server.on("/mode", HTTP_GET, handleMode);
  server.on("/volume", HTTP_GET, handleVolume);
  server.on("/lighttest", HTTP_GET, handleLightTest);
  server.begin();

  Serial.println("Web server ready.");
}

void loop() {
  server.handleClient();

  const int reading = analogRead(LDR_PIN);
  lastLdrValue = reading;

  // Hysteresis prevents flickering around the threshold.
  if (!lightIsOn && reading < LIGHT_ON_THRESHOLD - LIGHT_HYSTERESIS) {
    lightIsOn = true;
  } else if (lightIsOn && reading > LIGHT_ON_THRESHOLD + LIGHT_HYSTERESIS) {
    lightIsOn = false;
  }

  if (automaticMode && playerDetected) {
    if (lightIsOn && !hasStartedForCurrentLight) {
      player.play(1);
      isPlaying = true;
      hasStartedForCurrentLight = true;
      statusMessage = "Light turned on: starting the first track.";
    } else if (!lightIsOn && hasStartedForCurrentLight) {
      player.stop();
      isPlaying = false;
      hasStartedForCurrentLight = false;
      statusMessage = "Light turned off: music stopped.";
    }
  }

  delay(30);
}
